/* custom-tees-calibrate.css — staff print-box calibration tool (2026-06-10) */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --custom-tees-calibrate-gray: #66735f;
    --custom-tees-calibrate-gray-2: #8a8f7f;
    --custom-tees-calibrate-green-tint: #c9ebd4;
    --custom-tees-calibrate-green-dark: #136c34;
}
/* stylelint-enable color-no-hex */

* { box-sizing: border-box; }

body {
    margin: 0; font-family: 'Public Sans', Inter, Arial, sans-serif;
    background: var(--store-paper); color: var(--store-ink);
}

.cal-head {
    display: flex; align-items: flex-start; justify-content: space-between; gap: 16px;
    padding: 18px 22px; background: var(--store-green-950); color: var(--color-on-brand);
}
.cal-head h1 { margin: 0 0 6px; font-size: 19px; }
.cal-head p { margin: 0; font-size: 13px; opacity: 0.85; max-width: 760px; }
.cal-link { color: var(--custom-tees-calibrate-green-tint); font-size: 13px; white-space: nowrap; }

.cal-main {
    display: grid; grid-template-columns: 320px 1fr; gap: 18px;
    padding: 18px 22px; align-items: start;
}

/* Style list */
.cal-styles h2 { margin: 0 0 10px; font-size: 14px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--print-ink-soft); }
.style-list { display: grid; gap: 6px; max-height: calc(100vh - 160px); overflow: auto; padding-right: 4px; }

.style-item {
    display: flex; align-items: center; gap: 10px; width: 100%;
    padding: 8px; border: 1px solid var(--store-line); border-radius: 10px;
    background: var(--color-surface); cursor: pointer; text-align: left; font: inherit;
}
.style-item img { width: 44px; height: 44px; object-fit: contain; background: var(--store-green-50); border-radius: 6px; }
.style-item-name { flex: 1; font-weight: 700; font-size: 13px; }
.style-item-name small { display: block; font-weight: 400; color: var(--custom-tees-calibrate-gray); font-size: 11.5px; }
.style-item-state { font-size: 11px; color: var(--custom-tees-calibrate-gray-2); white-space: nowrap; }
.style-item-state.is-saved { color: var(--green-700); font-weight: 700; }
.style-item.is-active { border-color: var(--store-green-700); box-shadow: 0 0 0 2px rgb(47 125 59 / 18%); }
.cal-loading { padding: 14px; color: var(--custom-tees-calibrate-gray); font-size: 13px; }

/* Stage */
.cal-stage { background: var(--color-surface); border: 1px solid var(--store-line); border-radius: 14px; padding: 14px; }
.cal-toolbar { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 10px; }
.cal-tabs { display: flex; border: 1px solid var(--store-line); border-radius: 999px; overflow: hidden; }
.cal-tab { padding: 7px 18px; border: none; background: var(--color-surface); font: inherit; font-weight: 700; cursor: pointer; }
.cal-tab.is-active { background: var(--store-green-950); color: var(--color-on-brand); }
.cal-color { padding: 7px 10px; border: 1px solid var(--store-line); border-radius: 8px; font: inherit; }
.cal-coloronly { font-size: 12.5px; color: var(--print-ink-soft); display: inline-flex; align-items: center; gap: 6px; }

.cal-canvas-wrap {
    position: relative; display: grid; place-items: center;
    background: var(--store-green-50); border-radius: 10px; min-height: 420px; overflow: hidden;
    touch-action: none;
}
#cal-photo { max-width: 100%; max-height: 72vh; display: block; user-select: none; }

/* hidden attr must WIN over the display rule (author display beats the UA
   hidden style otherwise) — and the overlay is informational, never a hit
   target: without these two lines it invisibly swallowed every drag on the
   calibration box. (Erik bug report 2026-06-10) */
.cal-empty { position: absolute; inset: 0; display: grid; place-items: center; color: var(--custom-tees-calibrate-gray-2); font-size: 14px; pointer-events: none; }
.cal-empty[hidden] { display: none; }

.cal-box {
    position: absolute; border: 2px dashed var(--green-600); border-radius: 4px;
    background: rgb(22 163 74 / 8%); cursor: move;
}

.cal-box-label {
    position: absolute; top: -22px; left: 0; font-size: 11px; font-weight: 700;
    color: var(--green-700); white-space: nowrap;
}

.cal-box-handle {
    position: absolute; right: -13px; bottom: -13px; width: 26px; height: 26px;
    display: grid; place-items: center; background: var(--color-surface); color: var(--green-700);
    border: 2px solid var(--green-600); border-radius: 50%; cursor: nwse-resize; font-size: 11px;
    box-shadow: 0 2px 6px rgb(0 0 0 / 18%);
}

.cal-readout { margin: 10px 2px 0; font-size: 12px; color: var(--print-ink-soft); font-family: ui-monospace, Consolas, monospace; min-height: 16px; }

.cal-actions { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }

.cal-btn {
    display: inline-flex; align-items: center; gap: 7px;
    padding: 9px 14px; border: 1px solid var(--store-line); border-radius: 9px;
    background: var(--color-surface); font: inherit; font-weight: 600; cursor: pointer;
}
.cal-btn:hover { border-color: var(--store-green-700); }
.cal-btn-primary { background: var(--green-700); border-color: var(--green-700); color: var(--color-on-brand); }
.cal-btn-primary:hover { background: var(--custom-tees-calibrate-green-dark); }
