.cal-btn-danger { color: var(--red-700); }
.cal-btn-danger:hover { border-color: var(--red-700); }
.cal-note { margin: 10px 2px 0; font-size: 12.5px; color: var(--custom-tees-calibrate-gray); }

.cal-toasts { position: fixed; bottom: 16px; left: 50%; transform: translateX(-50%); display: grid; gap: 8px; z-index: 50; }

.cal-toast {
    background: var(--store-green-950); color: var(--color-on-brand); padding: 10px 16px; border-radius: 10px;
    font-size: 13px; box-shadow: 0 6px 18px rgb(0 0 0 / 25%);
}
.cal-toast.is-error { background: var(--print-red); }
.cal-toast.is-ok { background: var(--green-700); }

@media (width <= 900px) {
    .cal-main { grid-template-columns: 1fr; }
    .style-list { max-height: 300px; }
}
